-- =========================================================================
-- RESETEO DE SEQUENCES
-- =========================================================================
-- Despues de un INSERT con IDs explicitos, las sequences quedan en 1.
-- Esto las pone en max(id)+1 para evitar colisiones en futuros INSERTs.
-- Solo se aplica a las sequences asociadas a estas 22 tablas.

DO $$
DECLARE
  rec RECORD;
  max_val BIGINT;
BEGIN
  FOR rec IN
    SELECT
      s.relname AS seq_name,
      t.relname AS table_name,
      a.attname AS column_name
    FROM pg_class s
    JOIN pg_depend d ON d.objid = s.oid AND d.classid = 'pg_class'::regclass AND d.refclassid = 'pg_class'::regclass
    JOIN pg_class t ON t.oid = d.refobjid
    JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = d.refobjsubid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE s.relkind = 'S'
      AND n.nspname = 'public'
      AND t.relname IN (
        'barrios', 'ciudades', 'config', 'config_app', 'config_global',
        'empresa_rubros', 'empresa_subrubros', 'filtros',
        'filtros_busqueda_ia', 'grupo_categorias', 'grupo_subcategorias',
        'opciones_filtro', 'provincias', 'rubros', 'servicio_rubros',
        'servicio_subrubros', 'slider_tipos', 'subrubro_filtros',
        'subrubros', 'trabajo_filtros', 'trabajo_rubros',
        'trabajo_subrubros'
      )
  LOOP
    EXECUTE format('SELECT COALESCE(MAX(%I), 0) FROM public.%I', rec.column_name, rec.table_name) INTO max_val;
    IF max_val > 0 THEN
      EXECUTE format('SELECT setval(%L, %s, true)', 'public.' || rec.seq_name, max_val);
      RAISE NOTICE 'sequence %.% reseteada a %', rec.table_name, rec.seq_name, max_val;
    END IF;
  END LOOP;
END $$;

COMMIT;

